    def mask_account(self, account):
        try:
            mask_account = account[:6] + '*' * 6 + account[-6:]
            return mask_account
        except Exception as e:
            return None
        
    def generate_transaction_payload(self, network: dict, deploy: dict, tx_hash: str):
        return {
            "transactionHash": tx_hash,
            "metaData": {
                "name": network["network_name"],
                "type": deploy["name"]
            }
        }
        
    async def get_web3_with_check(self, address: str, network: dict, use_proxy: bool, retries=3, timeout=60):
        request_kwargs = {"timeout": timeout}

        proxy = self.get_next_proxy_for_account(address) if use_proxy else None

        if use_proxy and proxy:
            request_kwargs["proxies"] = {"http": proxy, "https": proxy}

        for attempt in range(retries):
            try:
                web3 = Web3(Web3.HTTPProvider(network["rpc_url"], request_kwargs=request_kwargs))
                web3.eth.get_block_number()
                return web3
            except Exception as e:
                if attempt < retries - 1:
                    await asyncio.sleep(3)
                    continue
                raise Exception(f"Failed to Connect to RPC: {str(e)}")
            
    async def get_token_balance(self, address: str, network: dict, use_proxy: bool):
        try:
            web3 = await self.get_web3_with_check(address, network, use_proxy)
            balance = web3.eth.get_balance(address)
            token_balance = web3.from_wei(balance, "ether")

            return token_balance
        except Exception as e:
            self.log(
                f"{Fore.CYAN+Style.BRIGHT}   Message  :{Style.RESET_ALL}"
                f"{Fore.RED+Style.BRIGHT} {str(e)} {Style.RESET_ALL}"
            )
            return None
        
    async def send_raw_transaction_with_retries(self, account, web3, tx, retries=5):
        for attempt in range(retries):
            try:
                signed_tx = web3.eth.account.sign_transaction(tx, account)
                raw_tx = web3.eth.send_raw_transaction(signed_tx.raw_transaction)
                tx_hash = web3.to_hex(raw_tx)
                return tx_hash
            except TransactionNotFound:
                pass
            except Exception as e:
                self.log(
                    f"{Fore.CYAN + Style.BRIGHT}   Message  :{Style.RESET_ALL}"
                    f"{Fore.YELLOW + Style.BRIGHT} [Attempt {attempt + 1}] Send TX Error: {str(e)} {Style.RESET_ALL}"
                )
            await asyncio.sleep(2 ** attempt)
        raise Exception("Transaction Hash Not Found After Maximum Retries")

    async def wait_for_receipt_with_retries(self, web3, tx_hash, retries=5):
        for attempt in range(retries):
            try:
                receipt = await asyncio.to_thread(web3.eth.wait_for_transaction_receipt, tx_hash, timeout=300)
                return receipt
            except TransactionNotFound:
                pass
            except Exception as e:
                self.log(
                    f"{Fore.CYAN + Style.BRIGHT}   Message  :{Style.RESET_ALL}"
                    f"{Fore.YELLOW + Style.BRIGHT} [Attempt {attempt + 1}] Wait for Receipt Error: {str(e)} {Style.RESET_ALL}"
                )
            await asyncio.sleep(2 ** attempt)
        raise Exception("Transaction Receipt Not Found After Maximum Retries")
    
    async def get_deploy_fee(self, address: str, network: dict, use_proxy: bool):
        try:
            web3 = await self.get_web3_with_check(address, network, use_proxy)

            contract_address = web3.to_checksum_address(self.CONTRACT_ADDRESS)
            token_contract = web3.eth.contract(address=contract_address, abi=self.CONTRACT_ABI)
            eth_amount = token_contract.functions.ethAmount().call()

            return eth_amount
        except Exception as e:
            self.log(
                f"{Fore.CYAN+Style.BRIGHT}   Message  :{Style.RESET_ALL}"
                f"{Fore.RED+Style.BRIGHT} {str(e)} {Style.RESET_ALL}"
            )
            return None
        
    async def perform_deploy(self, account: str, address: str, network: dict, deploy: dict, amount: int, use_proxy: bool):
        try:
            web3 = await self.get_web3_with_check(address, network, use_proxy)

            token_address = web3.to_checksum_address(self.CONTRACT_ADDRESS)
            token_contract = web3.eth.contract(address=token_address, abi=deploy["abi"])

            if deploy["name"] == "Timer":
                deploy_data = token_contract.functions.deployCounterAndTransfer(deploy["bytecode"])

            elif deploy["name"] == "ERC 20":
                token_name = deploy["constructor_args"]["name"]
                token_symbol = deploy["constructor_args"]["symbol"]
                deploy_data = token_contract.functions.deployTokenAndTransfer(deploy["bytecode"], token_name, token_symbol)
            
            elif deploy["name"] == "NFT":
                nft_name = deploy["constructor_args"]["name"]
                nft_symbol = deploy["constructor_args"]["symbol"]
                nft_url = deploy["constructor_args"]["url"]
                deploy_data = token_contract.functions.deployNFTAndTransfer(deploy["bytecode"], nft_name, nft_symbol, nft_url)

            contract_address = deploy_data.call({"from": address, "value": amount})

            estimated_gas = deploy_data.estimate_gas({"from": address, "value": amount})

            max_priority_fee = web3.to_wei(network["gas_fee"], "gwei")
            max_fee = max_priority_fee

            deploy_tx = deploy_data.build_transaction({
                "from": address,
                "value": amount,
                "gas": int(estimated_gas * 1.2),
                "maxFeePerGas": int(max_fee),
                "maxPriorityFeePerGas": int(max_priority_fee),
                "nonce": web3.eth.get_transaction_count(address, "pending"),
                "chainId": web3.eth.chain_id,
            })

            tx_hash = await self.send_raw_transaction_with_retries(account, web3, deploy_tx)
            receipt = await self.wait_for_receipt_with_retries(web3, tx_hash)
            block_number = receipt.blockNumber

            return tx_hash, block_number, contract_address
        except Exception as e:
            self.log(
                f"{Fore.CYAN+Style.BRIGHT}   Message  :{Style.RESET_ALL}"
                f"{Fore.RED+Style.BRIGHT} {str(e)} {Style.RESET_ALL}"
            )
            return None, None, None
        
